const cfg = $input.first().json;
const ids = String(cfg.SourceChannelIds || '').split(',').map(c => c.trim()).filter(Boolean);
if (!ids.length) return [{ json: { channelId: '' } }];
return ids.map(channelId => ({ json: { channelId } }));

const cfg = $('Standup Config').first().json;
const items = $input.all();
const hours = Number(cfg.LookbackHours) || 24;
const cutoff = (Date.now() - hours * 3600 * 1000) / 1000;
const blockerWords = String(cfg.BlockerKeywords || '').toLowerCase().split(',').map(x => x.trim()).filter(Boolean);
const msgs = [];
let skipped = 0;
for (const it of items) {
  const m = it.json;
  const text = String(m.text || '').trim();
  if (!text) { skipped++; continue; }
  const ts = Number(m.ts);
  if (!isNaN(ts) && ts > 0 && ts < cutoff) { skipped++; continue; }
  const user = (m.user_profile && m.user_profile.real_name) ? m.user_profile.real_name : (m.username || m.user || 'unknown');
  msgs.push({ user, text });
}
const combined = msgs.map(m => '[' + m.user + ']: ' + m.text).join('\n');
const keywordBlockers = msgs.filter(m => blockerWords.some(w => m.text.toLowerCase().includes(w)));
const channelCount = String(cfg.SourceChannelIds || '').split(',').map(x => x.trim()).filter(Boolean).length;
return [{ json: { messageCount: msgs.length, channelCount, keywordBlockerCount: keywordBlockers.length, keywordBlockerText: keywordBlockers.map(m => '[' + m.user + ']: ' + m.text).join('\n') || 'None matched by keyword.', combinedText: combined || 'No messages in the window.', skipped } }];

