const stats = $('Combine Messages').first().json;
const raw = String($input.item.json.text || '').trim();
let cleaned = raw.replace(/^```(?:json)?/i, '').replace(/```\s*$/, '').trim();
const s = cleaned.indexOf('{');
const e = cleaned.lastIndexOf('}');
if (s !== -1 && e > s) cleaned = cleaned.slice(s, e + 1);
let p = null;
try { p = JSON.parse(cleaned); } catch (err) { p = null; }
const arr = v => Array.isArray(v) ? v.filter(Boolean).map(String) : [];
const shipped = p ? arr(p.shipped) : [];
const blockers = p ? arr(p.blockers) : [];
const nextUp = p ? arr(p.nextUp) : [];
const needsAttention = p ? p.needsAttention === true : false;
const bullets = list => list.length ? list.map(l => '- ' + l).join('\n') : '- Nothing reported';
let digestText;
if (!p) {
  digestText = '*Standup digest*\n\nThe summariser returned output that could not be read. Raw messages from the last window:\n\n' + stats.combinedText.slice(0, 2500);
} else {
  digestText = ['*Standup digest* - ' + stats.messageCount + ' messages across ' + stats.channelCount + ' channel(s)', '', '*Shipped*', bullets(shipped), '', '*Blockers*', bullets(blockers), '', '*Next up*', bullets(nextUp)].join('\n');
}
const hasBlockers = blockers.length > 0 || needsAttention || stats.keywordBlockerCount > 0;
const blockerText = blockers.length ? bullets(blockers) : stats.keywordBlockerText;
return { json: { digestText, hasBlockers, needsAttention, blockerCount: blockers.length, blockerText, parseFailed: !p } };

